select distinct D.function_id
from sys_tenant_subscribe A
join sys_tenant_package B on A.package_id = B.id
join sys_tenant_package_function C on C.tenant_package_id = B.id
join sys_role_function D on D.function_id = C.function_id
join sys_role M on D.role_id = M.role_id and M.tenant_id = A.tenant_id
where A.use_yn = 1
    and A.effect_time  <= #{now}
    and A.expire_time >= #{now}
    and B.effect_time  <= #{now}
    and B.expire_time >= #{now}
    and A.tenant_id = #{tenantId}
    and D.role_id in (

        #{item}

    )

select distinct C.function_id
from sys_tenant_subscribe A
join sys_tenant_package B on A.package_id = B.id
